// Premium sparkle particles - twinkling stars
function Sparkles() {
  const sparkles = useMemo(
    () =>
      Array.from({ length: 80 }, (_, i) => ({
        id: i,
        left: `${Math.random() * 100}%`,
        top: `${Math.random() * 100}%`,
        delay: `${Math.random() * 5}s`,
        duration: `${1.5 + Math.random() * 2.5}s`,
        size: `${2 + Math.random() * 5}px`,
        type: Math.random() > 0.3 ? "gold" : "white",
      })),
    []
  );

  return (
    <div className="acul-sparkles">
      {sparkles.map((sparkle) => (
        <div
          key={sparkle.id}
          className={`acul-sparkle acul-sparkle--${sparkle.type}`}
          style={{
            left: sparkle.left,
            top: sparkle.top,
            animationDelay: sparkle.delay,
            animationDuration: sparkle.duration,
            width: sparkle.size,
            height: sparkle.size,
          }}
        />
      ))}
    </div>
  );
}

