function LoginScreen() {
  // Extracting attributes from hook made out of LoginInstance class of Auth0 React ACUL SDK
  const { login, texts, locales, alternateConnections, product } =
    useLoginManager();

  // Get product branding from ext-product param or URL (for dev testing)
  const devProduct =
    typeof window !== "undefined"
      ? new URLSearchParams(window.location.search).get("ext-product")
      : null;
  const activeProduct = product || devProduct || undefined;
  const productBranding = useProductBrandingByName(activeProduct);
  const isPremium = activeProduct === "premium";
  const isAtlas = activeProduct === "atlas-copco";

  // Debug logging
  if (activeProduct) {
    console.log("[ACUL] Product:", activeProduct, "Branding found:", !!productBranding);
  }

  // Apply theme classes to body
  useEffect(() => {
    if (isPremium) {
      document.body.classList.add("acul-premium-theme");
      document.body.classList.remove("acul-atlas-theme");
    } else if (isAtlas) {
      document.body.classList.add("acul-atlas-theme");
      document.body.classList.remove("acul-premium-theme");
    } else {
      document.body.classList.remove("acul-premium-theme");
      document.body.classList.remove("acul-atlas-theme");
    }
    return () => {
      document.body.classList.remove("acul-premium-theme");
      document.body.classList.remove("acul-atlas-theme");
    };
  }, [isPremium, isAtlas]);

  const showSeparator = alternateConnections && alternateConnections.length > 0;

  const separatorText = texts?.separatorText || locales?.page?.orText;
  document.title = texts?.pageTitle || locales?.page?.title;

  applyAuth0Theme(login, productBranding);

  const socialLoginAlignment = extractTokenValue(
    "--ul-theme-widget-social-buttons-layout"
  );

  const renderSocialLogins = (alignment: "top" | "bottom") => (
    <>
      {alignment === "bottom" && showSeparator && (
        <ULThemeSeparator text={separatorText} />
      )}
      <AlternativeLogins />
      {alignment === "top" && showSeparator && (
        <ULThemeSeparator text={separatorText} />
      )}
    </>
  );

  return (
    // Applying UDS theme overrides using the "theme-universal" class
    <ULThemePageLayout className="theme-universal">
      {/* DEBUG: Show if premium is active */}
      {isPremium && (
        <div style={{
          position: 'fixed',
          top: '10px',
          right: '10px',
          background: '#ffd700',
          color: '#000',
          padding: '8px 16px',
          borderRadius: '8px',
          fontWeight: 'bold',
          zIndex: 9999,
          fontSize: '14px'
        }}>
          ✨ PREMIUM MODE ACTIVE ✨
        </div>
      )}

      {/* Premium background effects */}
      {isPremium && (
        <>
          <RisingParticles />
          <Sparkles />
        </>
      )}

      {/* Atlas Copco industrial effects */}
      {isAtlas && (
        <>
          <TechnicalStatusPanel />
          <HexPattern />
          <IndustrialGears />
          <IndustrialParticles />
          <DataStreams />
        </>
      )}

      <ULThemeCard
        className={`w-full max-w-[400px] gap-0 ${isPremium ? "acul-golden-card" : ""} ${isAtlas ? "acul-atlas-card" : ""}`}
      >
        {/* Product badges */}
        {isPremium && (
          <div className="flex justify-center pt-4">
            <PremiumBadge />
          </div>
        )}
        {isAtlas && (
          <div className="flex justify-center pt-4">
            <AtlasBadge />
          </div>
        )}
        <Header />
        {socialLoginAlignment === "top" && renderSocialLogins("top")}
        <LoginForm />
        <Footer />
        {socialLoginAlignment !== "top" && renderSocialLogins("bottom")}
      </ULThemeCard>
    </ULThemePageLayout>
  );
}

export default LoginScreen;
